package alerts

// PriceEconomicsGenerationDisabled disables MVP generation of price/economics alerts.
// Reliable cost, unit economics, and margin data are not available in the active MVP.
// Do not enable without trustworthy unit economics. Types and rules remain for legacy reads.
const PriceEconomicsGenerationDisabled = true

// activeAlertTypes are generated by the active RunForAccount pipeline.
var activeAlertTypes = map[AlertType]struct{}{
	AlertTypeSalesRevenueDrop:         {},
	AlertTypeSalesOrdersDrop:          {},
	AlertTypeSKUOrdersDrop:            {},
	AlertTypeSKUNegativeContribution:  {},
	AlertTypeStockLowCoverage:         {},
	AlertTypeStockOOSRisk:             {},
	AlertTypeStockCriticalSKULowStock: {},
	AlertTypeFBOSurplusStorageRisk:    {},
	AlertTypeAdWeakCampaignEfficiency: {},
}

// legacyAlertTypes are readable in DB/UI history but must not be generated by the active pipeline.
var legacyAlertTypes = map[AlertType]struct{}{
	// Legacy sales (sku_revenue_drop superseded by sku_orders_drop in active rules).
	AlertTypeSKURevenueDrop: {},
	// Legacy SKU-level advertising (no reliable SKU ad attribution in MVP).
	AlertTypeAdSpendWithoutResult:       {},
	AlertTypeAdBudgetOnWeakSKU:          {},
	AlertTypeAdBudgetOnLowStockSKU:      {},
	AlertTypeStockAdvertisedSKULowStock: {},
	// Price/economics (generation disabled — see PriceEconomicsGenerationDisabled).
	AlertTypePriceBelowMinConstraint:            {},
	AlertTypePriceAboveMaxConstraint:            {},
	AlertTypeMarginRiskAtCurrentPrice:           {},
	AlertTypeMarginRiskAtMinPrice:               {},
	AlertTypeMissingPricingConstraintsForKeySKU: {},
}

// LegacyAlertTypes is kept for backward compatibility with callers using the exported map name.
var LegacyAlertTypes = legacyAlertTypes

func IsActiveAlertType(t AlertType) bool {
	_, ok := activeAlertTypes[t]
	return ok
}

func IsLegacyAlertType(t AlertType) bool {
	_, ok := legacyAlertTypes[t]
	return ok
}

func IsPriceEconomicsAlertType(t AlertType) bool {
	switch t {
	case AlertTypePriceBelowMinConstraint,
		AlertTypePriceAboveMaxConstraint,
		AlertTypeMarginRiskAtCurrentPrice,
		AlertTypeMarginRiskAtMinPrice,
		AlertTypeMissingPricingConstraintsForKeySKU:
		return true
	default:
		return false
	}
}

func IsPriceEconomicsAlertGroup(g AlertGroup) bool {
	return g == AlertGroupPriceEconomics
}

// AlertRiskBucket classifies one open alert into a mutually exclusive dashboard bucket.
func AlertRiskBucket(alertType AlertType, alertGroup AlertGroup) string {
	switch alertType {
	case AlertTypeFBOSurplusStorageRisk:
		return "surplus"
	case AlertTypeStockCriticalSKULowStock:
		return "critical_sku"
	case AlertTypeStockLowCoverage, AlertTypeStockOOSRisk, AlertTypeStockAdvertisedSKULowStock:
		return "stock"
	case AlertTypeAdSpendWithoutResult, AlertTypeAdWeakCampaignEfficiency,
		AlertTypeAdBudgetOnWeakSKU, AlertTypeAdBudgetOnLowStockSKU:
		return "advertising"
	case AlertTypeSKUOrdersDrop, AlertTypeSalesOrdersDrop, AlertTypeSalesRevenueDrop,
		AlertTypeSKUNegativeContribution, AlertTypeSKURevenueDrop:
		return "sales"
	}
	if IsPriceEconomicsAlertType(alertType) || IsPriceEconomicsAlertGroup(alertGroup) {
		return "other"
	}
	switch alertGroup {
	case AlertGroupStock:
		return "stock"
	case AlertGroupAdvertising:
		return "advertising"
	case AlertGroupSales:
		return "sales"
	default:
		return "other"
	}
}
